/* ============================================================
   ANOTIFY · 设计令牌（Design Tokens）· 全站唯一色彩来源
   ------------------------------------------------------------
   使用规则（务必遵守，保证全站一致）：

   ① 中性色 —— 承载 ~90% 的界面：所有背景 / 文字 / 边框。
   ② 品牌色 indigo（唯一）—— 品牌标识、主按钮、active、focus、
      链接，以及【默认的数据可视化色】（热力图、主趋势线…）。
   ③ 语义色（绿/红/黄）—— 只用于表达"状态含义"，且只小面积：
      状态点、徽章、细线、小占比图表。
      ✗ 禁止大面积填充  ✗ 禁止纯装饰。
   ④ 比例基准 ≈ 70% 中性 / 20% indigo / 10% 语义。

   改颜色只改这里，全站生效。不要在下层页面硬编码色值。
   ============================================================ */

:root {
	/* ── 中性色 Neutral ─────────────────────────────── */
	--bg: #050508; /* 页面底 */
	--bg-raise: #08080d; /* 侧栏/凸起底 */
	--surface-1: rgba(255, 255, 255, 0.02); /* 卡片 */
	--surface-2: rgba(255, 255, 255, 0.04); /* 悬浮/输入 */
	--line: rgba(255, 255, 255, 0.08); /* 弱分隔线 */
	--line-strong: rgba(255, 255, 255, 0.14); /* 强分隔线 */
	--text: #ececf1; /* 主文字 */
	--muted: rgba(236, 236, 241, 0.55); /* 次要文字 */
	--faint: rgba(236, 236, 241, 0.32); /* 极弱文字 */

	/* ── 品牌色 Brand（唯一 accent）────────────────── */
	--accent: #8b8bfd; /* indigo 主色 */
	--accent-strong: #a6a6ff; /* hover/提亮 */
	--accent-soft: rgba(139, 139, 253, 0.12); /* 品牌色浅底 */
	/* 品牌色数据可视化梯度（热力图等，由浅到深 5 级）*/
	--accent-1: rgba(139, 139, 253, 0.22);
	--accent-2: rgba(139, 139, 253, 0.42);
	--accent-3: rgba(139, 139, 253, 0.68);
	--accent-4: #8b8bfd;

	/* ── 语义色 Semantic（仅表状态，小面积）────────── */
	--success: #34d399; /* 成功 */
	--error: #fb7185; /* 失败/危险 */
	--warn: #fbbf24; /* 中断/警告 */
	--info: var(--accent); /* 信息 → 复用品牌色，不引入新色相 */
	/* 语义色配套浅底（徽章背景用，10-12% 透明度）*/
	--success-soft: rgba(52, 211, 153, 0.12);
	--error-soft: rgba(251, 113, 133, 0.12);
	--warn-soft: rgba(251, 191, 36, 0.12);
}

