			'  <header class="sticky top-0 z-20 flex h-16 items-center justify-between gap-4 border-b border-white/[0.06] bg-[#050508]/80 px-5 backdrop-blur-md sm:px-8">' +
			'    <div class="flex items-center gap-3">' +
