import { chromium } from "playwright-core";
const pages = ["keys.html", "security.html", "docs.html"];
const browser = await chromium.launch({ channel: "chrome", headless: true, args: ["--no-sandbox"] });
let allOk = true;
for (const p of pages) {
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errs = [], failed = [];
  page.on("pageerror", (e) => errs.push(String(e)));
  page.on("console", (m) => { if (m.type() === "error") errs.push(m.text()); });
  page.on("requestfailed", (r) => failed.push(`${r.method()} ${r.url()} → ${r.failure()?.errorText}`));
  const resp404 = [];
  page.on("response", (r) => { if (r.status() >= 400) resp404.push(`${r.status()} ${r.url()}`); });
  await page.goto(`http://localhost:5715/${p}`, { waitUntil: "networkidle" });
  await page.waitForTimeout(1200);
  // 溢出检测
  const overflow = await page.evaluate(() => {
    const vw = window.innerWidth, out = [];
    for (const el of document.querySelectorAll("body *")) {
      const r = el.getBoundingClientRect();
      if (r.right > vw + 5 && !el.closest("pre") && !el.closest(".overflow-x-auto")) out.push(`${el.tagName}.${String(el.className).slice(0,40)} right=${Math.round(r.right)}`);
    }
    return out.slice(0, 5);
  });
  await page.screenshot({ path: `/tmp/t14-${p}.png`, fullPage: false });
  console.log(`== ${p}: jsErr=${errs.length} reqFail=${failed.length} http4xx=${resp404.length} overflow=${overflow.length}`);
  errs.slice(0,3).forEach(e => console.log("  JSERR:", e.slice(0,150)));
  failed.slice(0,3).forEach(e => console.log("  REQFAIL:", e.slice(0,150)));
  resp404.slice(0,3).forEach(e => console.log("  4xx:", e.slice(0,150)));
  overflow.forEach(e => console.log("  OVERFLOW:", e));
  if (errs.length || failed.length || resp404.length || overflow.length) allOk = false;
  await page.close();
}
await browser.close();
console.log(allOk ? "ALL-OK" : "HAS-ISSUES");
EOF
